import dev.hua.ptcglive.engine.*;
import dev.hua.ptcglive.engine.effect.*;
import dev.hua.ptcglive.engine.field.*;
import dev.hua.ptcglive.rules.*;
import java.util.*;

/** Exercises the printed SD100 programs through authoritative gameplay, with owned 60-card fixtures. */
public final class StarterDeck100PokemonTest {
    static final UUID A=StarterDeck100CombatTest.A,B=StarterDeck100CombatTest.B;
    static final CombatCatalog COMBAT=StarterDeck100CombatTest.COMBAT;
    static String id(int n){return StarterDeck100CommonTest.id(n);}
    static void check(boolean ok,String reason){StarterDeck100CombatTest.check(ok,reason);}
    static List<String> chain(String card){var result=new ArrayList<String>();while(card!=null){result.addFirst(card);card=COMBAT.pokemon(card).orElseThrow().evolvesFromDefinitionId();}return result;}
    static List<CardInstance> deck(UUID owner,int pokemon,String...extras){
        var line=chain(id(pokemon));var ids=new ArrayList<String>();for(int i=0;i<16;i++)ids.add(line.getFirst());
        for(var evo:line.subList(1,line.size()))for(int i=0;i<5;i++)ids.add(evo);
        var types=new LinkedHashSet<EnergyType>();types.add(EnergyType.GRASS);for(var a:COMBAT.pokemon(id(pokemon)).orElseThrow().attacks())types.addAll(a.energyCost().keySet());types.remove(EnergyType.COLORLESS);
        for(var type:types)for(int i=0;i<8;i++)ids.add("sd100_cn_"+type.name().toLowerCase(Locale.ROOT)+"_energy");
        for(var extra:extras)for(int i=0;i<4;i++)ids.add(extra);
        check(ids.size()<=60,"fixture exceeds 60");while(ids.size()<60)ids.add("sd100_cn_grass_energy");
        return ids.stream().map(s->StarterDeck100CombatTest.card(owner,s)).toList();
    }
    static ServerMatch game(int pokemon,String...extras){return game(pokemon,1,extras);}
    static ServerMatch game(int pokemon,int opponent,String...extras){return gameSeed(pokemon,opponent,0,extras);}
    static ServerMatch gameSeed(int pokemon,int opponent,int firstSeed,String...extras){
        var root=chain(id(pokemon)).getFirst();var oppRoot=chain(id(opponent)).getFirst();
        for(int seed=firstSeed;seed<firstSeed+200;seed++){
            var m=new ServerMatch(A,B,deck(A,pokemon,extras),deck(B,opponent),StarterDeck100CombatTest.RULE,StarterDeck100CombatTest.CARDS,COMBAT,new ServerRandom(seed));OpeningTestSupport.decideOrder(m,A,B);
            if(m.privateView(A).hand().stream().filter(c->c.definitionId().equals(root)).count()<2||m.privateView(B).hand().stream().filter(c->c.definitionId().equals(oppRoot)).count()<2)continue;
            // Explicit root selections avoid an extra Basic taking the Active position in a mixed deck.
            OpeningTestSupport.complete(m,A,B,1);
            if(!m.activePokemonView(A).topCardId().equals(root)||!m.activePokemonView(B).topCardId().equals(oppRoot))continue;
            m.endTurn(A);m.endTurn(B);evolve(m,A,m.activePokemonView(A).pokemonId(),pokemon);
            return m;
        }throw new AssertionError("No fixture for "+pokemon);
    }
    static CardInstance hand(ServerMatch m,String id){var found=m.privateView(A).hand().stream().filter(c->c.definitionId().equals(id)).findFirst();if(found.isPresent())return found.get();var c=m.privateView(A).deck().stream().filter(x->x.definitionId().equals(id)).findFirst().orElseThrow();m.searchOwnDeckToHandByEffect(A,List.of(c.instanceId()));return c;}
    static void evolve(ServerMatch m,UUID owner,UUID target,int pokemon){check(owner.equals(A),"fixture evolution actor");for(var evo:chain(id(pokemon)).subList(1,chain(id(pokemon)).size())){m.evolveByEffect(A,target,hand(m,evo).instanceId(),EvolutionPermission.CARD_EFFECT_ALL_TIMING);declineEntryTriggers(m);}}
    static void declineEntryTriggers(ServerMatch m){while(m.triggerOrderPrompt()!=null){var p=m.triggerOrderPrompt();check(p.optionalDecision(),"unexpected mandatory fixture trigger");m.decideTriggeredEffect(p.choosingPlayer(),p.id(),false);}}
    static void charge(ServerMatch m,int attack){for(var e:COMBAT.pokemon(m.activePokemonView(A).topCardId()).orElseThrow().attacks().get(attack).energyCost().entrySet())for(int i=0;i<e.getValue();i++)StarterDeck100EnergyTest.attach(m,A,A,"sd100_cn_"+(e.getKey()==EnergyType.COLORLESS?"grass":e.getKey().name().toLowerCase(Locale.ROOT))+"_energy",m.activePokemonView(A).pokemonId());}
    static void attack(ServerMatch m,int index){charge(m,index);m.attack(A,COMBAT.pokemon(m.activePokemonView(A).topCardId()).orElseThrow().attacks().get(index).id());}
    static BattlefieldState.PokemonView view(ServerMatch m,UUID player,UUID supplied){UUID host=PokemonIdentityTestSupport.logical(m,player,supplied);if(m.activePokemonView(player).pokemonId().equals(host))return m.activePokemonView(player);return m.benchPokemonView(player).stream().filter(p->p.pokemonId().equals(host)).findFirst().orElseThrow();}
    static void ability(ServerMatch m,UUID host){var view=view(m,A,host);m.useAbility(A,host,COMBAT.pokemon(view.topCardId()).orElseThrow().abilities().getFirst().id());}
    static void select(ServerMatch m,int count){var p=m.effectCardPrompt(A);check(p!=null,"missing card selection");m.submitEffectCards(A,p.resolutionId(),p.step(),p.candidates().stream().limit(count).map(CardInstance::instanceId).toList());if(m.effectCardReveal()!=null)m.acknowledgeEffectReveal(B,m.effectCardReveal().id());}
    static void choosePokemon(ServerMatch m,UUID chosen){var p=m.effectPokemonPrompt(A);m.chooseEffectPokemon(A,p.resolutionId(),p.step(),chosen);}
    static void trim(ServerMatch m,int size){var cards=m.privateView(A).hand();if(cards.size()>size)m.discardHandCardsByEffect(A,A,cards.subList(size,cards.size()).stream().map(CardInstance::instanceId).toList());}
    public static void main(String[] args){rondo();excitingStage();springBloom();retreatAura();searchBench();mew();discardDamage();attachments();quickShooting();ancientFreeze();punkShock();wakeUpSlap();rewindBeam();maxShock();System.out.println("StarterDeck100PokemonTest passed: real SD100 abilities, search, Energy costs/distribution, damage/status and evolution programs");}
    static void rondo(){for(int n:List.of(56,92,137)){var m=game(n);UUID active=m.activePokemonView(A).pokemonId(),bench=m.benchPokemonView(A).getFirst().pokemonId();String ab=COMBAT.pokemon(id(n)).orElseThrow().abilities().getFirst().id();check(!m.canUseAbility(A,bench,ab),"Fleet Footed usable on Bench");int before=m.privateView(A).hand().size();ability(m,active);check(m.privateView(A).hand().size()==before+1&&!m.canUseAbility(A,active,ab),"Fleet Footed not once per turn");attack(m,0);check(m.lastAttack().finalDamage()==(n==56?120:60),"Rondo must count both Benches before weakness: "+n);}}
    static void excitingStage(){for(boolean benched:List.of(false,true)){var m=game(14);trim(m,0);UUID source=benched?m.benchPokemonView(A).getFirst().pokemonId():m.activePokemonView(A).pokemonId();ability(m,source);check(m.privateView(A).hand().size()==(benched?3:4),"Exciting Stage draw-to limit");UUID other=benched?m.activePokemonView(A).pokemonId():m.benchPokemonView(A).getFirst().pokemonId();TopDeckLookTest.rejects(()->ability(m,other));}}
    static void springBloom(){var m=game(16,id(1));var v=hand(m,id(1));m.playBasicPokemonToBench(A,v.instanceId());UUID source=m.activePokemonView(A).pokemonId(),target=m.benchPokemonView(A).getFirst().pokemonId();for(int i=0;i<2;i++){hand(m,"sd100_cn_grass_energy");ability(m,source);var p=m.effectPokemonPrompt(A);check(p!=null&&p.targets().stream().noneMatch(t->t.pokemonId().equals(PokemonIdentityTestSupport.logical(m,A,v.instanceId()))),"Spring Bloom offered Rule Box Pokemon");TopDeckLookTest.rejects(()->m.chooseEffectPokemon(A,p.resolutionId(),p.step(),PokemonIdentityTestSupport.logical(m,A,v.instanceId())));choosePokemon(m,target);select(m,1);check(view(m,A,target).attachedEnergyIds().size()==i+1,"Spring Bloom did not attach or imposed once-per-turn");}}
    static void retreatAura(){var m=game(48);UUID source=m.activePokemonView(A).pokemonId();int original=m.activeRetreatCost(A);StarterDeck100EnergyTest.attach(m,A,A,"sd100_cn_fire_energy",source);check(m.activeRetreatCost(A)==Math.max(0,original-2),"Fire Energy retreat reduction absent");m.disableAbilityEffectsByEffect(A,A,source);check(m.activeRetreatCost(A)==original,"suppressed Ninetales retained aura");}
    static void searchBench(){for(int n:List.of(2,116)){var m=game(n,id(1));attack(m,0);var p=m.effectCardPrompt(A);check(p!=null&&p.candidates().stream().allMatch(c->m.cardDefinition(c.definitionId()).basicPokemon()&&(n==2?c.definitionId().equals(id(2)):m.cardDefinition(c.definitionId()).pokemonFamilies().contains(PokemonFamily.RAPID_STRIKE))),"Bench search identity/style filter");select(m,n==2?1:3);check(m.benchPokemonView(A).size()==(n==2?2:4),"Bench search wrong cardinality");}}
    static void mew(){var m=game(171,id(373));UUID source=m.activePokemonView(A).pokemonId();TopDeckLookTest.rejects(()->ability(m,m.benchPokemonView(A).getFirst().pokemonId()));var deck=m.privateView(A).deck();var top=Set.copyOf(deck.subList(deck.size()-6,deck.size()));ability(m,source);var p=m.effectCardPrompt(A);check(Set.copyOf(p.inspectedCards()).equals(top)&&p.candidates().stream().allMatch(c->c.definitionId().equals(id(373))),"Mysterious Tail not top-six Items");select(m,0);TopDeckLookTest.rejects(()->ability(m,source));}
    static void discardDamage(){for(int picked:List.of(0,2)){var m=game(62);hand(m,"sd100_cn_grass_energy");hand(m,"sd100_cn_fire_energy");attack(m,1);check(m.activePokemonView(B).damage()==0,"damage committed before Energy choice");select(m,picked);check(m.lastAttack().finalDamage()==picked*120,"Fling Fire must be60 per discarded Basic Energy then weakness");}
        var m=game(37);charge(m,1);var bench=m.benchPokemonView(A).getFirst().pokemonId();StarterDeck100EnergyTest.attach(m,A,A,"sd100_cn_grass_energy",bench);m.attack(A,COMBAT.pokemon(id(37)).orElseThrow().attacks().get(1).id());var p=m.effectCardPrompt(A);check(p.candidates().size()==4,"Raging Repeated Strike did not include both Active and Bench Energy");select(m,2);check(m.lastAttack().finalDamage()==180,"Raging Repeated Strike discard count");}
    static void attachments(){var m=game(55);hand(m,"sd100_cn_fire_energy");attack(m,0);select(m,1);check(m.activePokemonView(A).attachedEnergyIds().size()==2,"Heat Dash did not attach after damage");
        m=game(63);hand(m,"sd100_cn_grass_energy");hand(m,"sd100_cn_fire_energy");attack(m,0);select(m,2);var p=m.effectAttachmentPrompt(A);check(p!=null&&m.hasPendingEnergyDistribution(),"Bursting Power missing distribution");var energies=p.cards();m.assignEffectEnergyDistribution(A,p.resolutionId(),p.step(),energies.getFirst().instanceId(),m.activePokemonView(A).pokemonId());m.assignEffectEnergyDistribution(A,p.resolutionId(),p.step(),energies.getLast().instanceId(),m.benchPokemonView(A).getFirst().pokemonId());m.confirmEffectEnergyDistribution(A,p.resolutionId(),p.step());check(m.benchPokemonView(A).getFirst().attachedEnergyIds().size()==1,"Bursting Power failed distributed attachment");}
    static void quickShooting(){var m=game(118);UUID target=m.benchPokemonView(B).getFirst().pokemonId(),source=m.activePokemonView(A).pokemonId();m.useAbility(A,source,COMBAT.pokemon(id(118)).orElseThrow().abilities().getFirst().id(),target);check(view(m,B,target).damage()==20&&m.activePokemonView(B).damage()==0,"Quick Shooting wrong target/counters");TopDeckLookTest.rejects(()->ability(m,source));}
    static void ancientFreeze(){for(int opponent:List.of(1,13)){var m=game(124,opponent);attack(m,0);check(m.mayAttack(B)==(opponent==13),"Ancient Freeze V-only attack lock");if(opponent==1){m.switchActiveByEffect(B,B,m.benchPokemonView(B).getFirst().pokemonId());check(m.mayAttack(B),"switching did not clear attack lock");}}}
    static void punkShock(){for(int choice:List.of(0,1)){var m=game(158);attack(m,0);var p=m.effectChoicePrompt(A);check(p!=null&&p.optionsZh().size()==2,"Punk Shock optional branch");m.chooseEffectOption(A,p.resolutionId(),p.step(),choice);check(m.activePokemonView(A).damage()==(choice==0?70:0)&&m.activePokemonView(B).conditions().contains(SpecialCondition.PARALYZED)==(choice==0),"Punk Shock branch effects separated");}}
    static void wakeUpSlap(){for(boolean status:List.of(false,true)){var m=game(166);if(status)m.applySpecialConditionByEffect(A,B,SpecialCondition.CONFUSED);attack(m,1);check(m.lastAttack().finalDamage()==(status?120:30)&&m.activePokemonView(B).conditions().isEmpty(),"Wake-Up Slap must add damage before clearing status");}}
    static void rewindBeam(){var plain=game(188);attack(plain,1);check(plain.lastAttack().finalDamage()==180&&!plain.hasPendingEffectChoice(),"Rewind Beam failed against unevolved Pokemon");
        var m=game(188,150);m.endTurn(A);var evo=m.privateView(B).deck().stream().filter(c->c.definitionId().equals(id(150))).findFirst().orElseThrow();m.searchOwnDeckToHandByEffect(B,List.of(evo.instanceId()));m.evolveByEffect(B,m.activePokemonView(B).pokemonId(),evo.instanceId(),EvolutionPermission.CARD_EFFECT_ALL_TIMING);String underlying=chain(id(150)).getFirst();m.endTurn(B);attack(m,1);check(m.activePokemonView(B).topCardId().equals(underlying)&&m.activePokemonView(B).damage()==180&&m.privateView(B).hand().contains(evo),"Rewind Beam did not return exactly the top Evolution and preserve damage");}
    static void maxShock(){for(boolean behind:List.of(false,true)){var m=game(150);if(behind){m.endTurn(A);m.knockOutPokemonByEffect(B,A,m.benchPokemonView(A).getFirst().pokemonId());StarterDeck100CombatTest.settleKnockouts(m);m.endTurn(B);}attack(m,0);check(m.activePokemonView(B).conditions().contains(SpecialCondition.PARALYZED)==behind,"Max Shock prize comparison reversed");}}
}
